try {{
    $bytes = [Convert]::FromBase64String(($b64 -replace "\s", ""))
    [IO.File]::WriteAllBytes((Resolve-Path $MAIN), $bytes)
    Write-Host "main.py replaced from regenerated payload."
}} catch {{
    Write-Host "Write failed. Restoring backup..."
    Copy-Item $backup $MAIN -Force
    throw
}}

Write-Host ""
Write-Host "Checking Python syntax..."
python -m py_compile .\main.py
if ($LASTEXITCODE -ne 0) {{
    Write-Host ""
    Write-Host "Syntax failed. Restoring backup..."
    Copy-Item $backup $MAIN -Force
    python -m py_compile .\main.py
    exit 1
}}

Write-Host ""
Write-Host "Checking expected guard constants and functions..."
$verifyFile = ".\verify_regenerated_main.py"
@'
from pathlib import Path
text = Path("main.py").read_text(encoding="utf-8")
required = [
    'QFOS_SIDEWAYS_HARD_EXPOSURE_PCT',
    '_qfos_guard_filter_new_buys',
    '_qfos_guard_profit_engine_reduce_if_needed',
    'def _qfos_guard_policy_class_from_features',
    '_qfos_guard_downgrade_trade_class',
    'QFOS_RESCUE_MAX_RESCUE_BUYS_PER_HOUR_SIDEWAYS = globals().get("QFOS_RESCUE_MAX_RESCUE_BUYS_PER_HOUR_SIDEWAYS", 4)',
]
missing = [x for x in required if x not in text]
if missing:
    raise SystemExit("MISSING_EXPECTED_MARKERS: " + repr(missing))
print("MAIN_VERIFY_OK")
'@ | Set-Content $verifyFile -Encoding UTF8
python $verifyFile
Remove-Item $verifyFile -Force -ErrorAction SilentlyContinue
if ($LASTEXITCODE -ne 0) {{
    Write-Host ""
    Write-Host "Marker verification failed. Restoring backup..."
    Copy-Item $backup $MAIN -Force
    exit 1
}}

Write-Host ""
Write-Host "Git status summary:"
git status --short

Write-Host ""
Write-Host "Regenerated main.py installed successfully."
Write-Host "Backup kept at: $backup"
Write-Host "Next: restart the bot/API containers or Python process so the new main.py is loaded."
